<?php require_once '../includes/auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$n=trim($_POST['name']??'');$e=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$p=$_POST['password']??'';if($n&&$e&&strlen($p)>=8){try{$q=$pdo->prepare('INSERT INTO users(name,email,password_hash)VALUES(?,?,?)');$q->execute([$n,$e,password_hash($p,PASSWORD_DEFAULT)]);$_SESSION['user_id']=$pdo->lastInsertId();go('/seller/dashboard.php');}catch(PDOException $x){$error='Email already registered.';}}else $error='Name, valid email, and password of 8+ characters are required.';}$title='Register';require '../includes/header.php';?><h1>Register</h1><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="card card-body col-lg-6"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input class="form-control mb-2" name="name" placeholder="Name" required><input class="form-control mb-2" type="email" name="email" placeholder="Email" required><input class="form-control mb-2" type="password" name="password" placeholder="Password (8+ characters)" required><button class="btn btn-success">Register</button></form><?php require '../includes/footer.php';?>